import { BrowserRouter, Link, Route, Routes } from 'react-router-dom';

import { useContext } from 'react';
import { booleanContext, incrementContext, messageContext, messageIds } from '../Context';


 const Menu = () => {
   const [showLogOut, setShowLogout]=useState(false);
const {newMessage, setNewMessage} = useContext(messageContext)
    const [showLogIn, setShowLogIn]=useState(true);
    const {ids, setIds} = useContext(messageIds)
const currentUser = localStorage.getItem("email")
 const isLoggedIn = localStorage.getItem("Logged In");
 console.log(typeof ids);

useEffect(()=>{
if(localStorage.getItem("Logged In", true)){
setShowLogIn(false)
setShowLogout(true)

}

},[isLoggedIn])
useEffect (()=>{
},[newMessage])

  return (
   <>

   <nav className="navbar navbar-expand-lg navbar-text-light bg-dark">

  <a className="navbar-brand" href="/">JT's Messenger</a>
  <button
    className="navbar-toggler"
    type="button"
    data-toggle="collapse"
    data-target="#navbarSupportedContent"
    aria-controls="navbarSupportedContent"
    aria-expanded="false"
    aria-label="Toggle navigation"

  >
    <span className="navbar-toggler-icon"></span>
  </button>

  <div className="collapse navbar-collapse" id="navbarSupportedContent">
    <ul className="navbar-nav mr-auto">
      <li className="user-item">

         {(newMessage || localStorage.getItem("recievedMessages")
        && (ids && !ids.includes(currentUser) )) ?
                                        <span className='nbr-msg'></span> 
                                            : null
                                    }

        <a className="nav-link" href='/'

        >Home</a>
      </li>
      <li className="nav-item">
        <a className="nav-link" href='/products'>Products</a>
      </li>
      <li className="nav-item">
        <a className="nav-link" href='/about'>About</a>
      </li>
    </ul>
    <div className="form-inline my-2 my-lg-0">
      <ul className="navbar-nav mr-auto2">
        <li className="nav-item">
          {/* <Link className="nav-link" to={{
    pathname: "/cart",
    search: "?sort=name",
    hash: "#the-hash",
    state: { fromDashboard: true }
  }}>
         Cart({cart})
          </Link> */}
          </li>

   <li className="nav-item">

            <a className="nav-link" 
    href= "/admin">
        Admin
          </a>
      </li>
        <li className="nav-item">

           {/* { showRegister ? <a className="nav-link" href='/register'>Register</a> : null } */}
        </li>
        <li className="nav-item">


            { showLogIn ?   <a className="nav-link" href='/'>Login</a> : null }
        </li>
        <li className="nav-item">

           {/* { showProfile ?   */}
           <a className="nav-link " href='/userList'>People</a> 

        {/* //    : null } */}
        </li>
        <li className="nav-item">

           { showLogOut ? 
            <a className="nav-link text-danger" href='/logout'>Logout</a> 
             : null }


        </li>
      </ul>

    </div>
  </div>
</nav>
{/* // <app-shopping-cart *ngIf=""></app-shopping-cart>
// <router-outlet></router-outlet> */}



   </>
  )
}

export default Menu;
